import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Set-Membership.md","filePath":"manual-en/Set-Membership.md","lastUpdated":1785684581000}'),n={name:"manual-en/Set-Membership.md"};function r(o,e,l,m,u,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h4 id="_7-7-5-set-membership-functions" tabindex="-1">7.7.5 Set-Membership Functions <a class="header-anchor" href="#_7-7-5-set-membership-functions" aria-label="Permalink to &quot;7.7.5 Set-Membership Functions&quot;">​</a></h4><p>Set membership functions determine whether a value is a member of a set. They take a set of numeric arguments or a set of string arguments, and produce Boolean results.</p><p>String comparisons are performed according to the rules given in <a href="./Relational-Operators">Relational Operators</a>. User-missing string values are treated as valid values.</p><p>Function: __<strong>ANY</strong> <em>( value, set [, set]…)</em></p><p>Returns true if value is equal to any of the set values, and false otherwise. For numeric arguments, returns system-missing if value is system-missing or if all the values in set are system-missing. If value</p><p>Function: __<strong>RANGE</strong> <em>( value, low, high [, low, high]…)</em></p><p>Returns true if value is in any of the intervals bounded by low and high inclusive, and false otherwise. low and high must be given in pairs. Returns system-missing if any high is less than its low or, for numeric arguments, if value is system-missing or if all the low-high pairs contain one (or two) system-missing values. A pair does not match value if either low or high is missing, even if value equals the non-missing endpoint.</p>',7)])])}const f=s(n,[["render",r]]);export{c as __pageData,f as default};
